const compact=n=>Number(n)>=1e6?'UGX '+(Number(n)/1e6).toFixed(2)+'m':money(n);
const num=n=>new Intl.NumberFormat('en-UG',{maximumFractionDigits:0}).format(Number(n)||0);
const byId=(arr,id)=>arr.find(x=>x.id===id);const marketName=id=>id==='all'?'All Markets':byId(D.markets,id)?.name||id;
const sum=(a,key)=>a.reduce((x,y)=>x+(Number(typeof key==='function'?key(y):y[key])||0),0);
const unique=(a,key)=>new Set(a.map(x=>typeof key==='function'?key(x):x[key]).filter(Boolean)).size;
const openCases=D.requests.filter(x=>x.status==='OPEN');const currentCases=()=>D.requests.filter(x=>['OPEN','ESCALATED','WAITING_INFO','UNDER_REVIEW'].includes(x.status));
const REQUEST_LABEL={ONBOARDING:'Onboarding',RENTAL:'Rental applications',KYC:'KYC verification',RECONCILIATION:'Reconciliation',SUPPORT:'Support tickets',CONTRACT:'RentContracts',IMPORT:'Import review',GATE:'Gate / Stock'};
const pages={global:{label:'Global Operations',icon:'grid',group:'COMMAND CENTER'},requests:{label:'Request Center',icon:'clipboard',group:'COMMAND CENTER'},markets:{label:'Market Intelligence',icon:'building',group:'INTELLIGENCE'},vendors:{label:'Vendor Overview',icon:'users',group:'INTELLIGENCE'},facilities:{label:'Facility Intelligence',icon:'shop',group:'INTELLIGENCE'},suppliers:{label:'Supplier Intelligence',icon:'truck',group:'INTELLIGENCE'},finance:{label:'Finance & Evidence',icon:'wallet',group:'INTELLIGENCE'},staff:{label:'Staff & MarketMasters',icon:'badge',group:'ADMINISTRATION'},roles:{label:'RBAC Governance',icon:'shield',group:'ADMINISTRATION'},imports:{label:'Import Integrity',icon:'file',group:'OPERATIONS'},gate:{label:'Gate & Stock',icon:'gate',group:'OPERATIONS'},rental:{label:'Rental Readiness',icon:'filecheck',group:'OPERATIONS'},'journey':{label:'Rental Application Journey',icon:'filecheck',group:'EXPERIENCES'},'supply-journey':{label:'Supplier → Gate Journey',icon:'truck',group:'EXPERIENCES'},'shop-finder':{label:'Public Shop Finder',icon:'search',group:'EXPERIENCES'},'my-business':{label:'My Workspace',icon:'home',group:'EXPERIENCES'},library:{label:'179 KPI Library',icon:'layers',group:'DESIGN REVIEW'},design:{label:'Design System',icon:'settings',group:'DESIGN REVIEW'},review:{label:'PM Approval',icon:'check',group:'DESIGN REVIEW'}};
