 grid([metric('Pending requests',num(rows.length),'Distinct OPEN case IDs','clipboard','requests'),metric('Assigned to A. Kato',num(assigned),'Illustrative responsible reviewer','users','requests'),metric('Unassigned',num(unassigned),'Explicitly no owner in sample','alert','requests','warn'),metric('Past-due review targets',num(aged),'Illustrative dueAt deadlines, not legal SLAs','clock','requests','bad')])+
 `<div class="section-grid">${panel('Case source breakdown','Click a category to apply exact Request Center filtering',bars(types.map(x=>({name:x.label,key:x.value,value:rows.filter(y=>y.type===x.value).length})),'requests','requestsList','type')+`<div class="divider" style="margin:14px 0"></div>${miniStat('Category subtotal',num(rows.length))}`)}${panel('Source-specific actions','Actions are delegated to their original workflow owners',`<div class="v-stack">${[['Onboarding + KYC','Identity review, TIN/NIN and document evidence'],['Rental + RentContracts','Facility allocation and accepted tenancy requirements'],['Reconciliation','No financial writes without approved policy'],['Support / Import / Gate','Separate ticket and operational exception owners']].map(x=>`<div class="note-card"><strong>${x[0]}</strong><div class="muted tiny" style="margin-top:5px">${x[1]}</div></div>`).join('')}</div>`)} </div>`+
 smartTable({id:'requestsList',title:'Authorized request worklist',description:'Distinct synthetic open cases; current Market, status and filters apply to counts and full-population export.',rows,columns:[col('id','Case',r=>details('request',r.id,r.id)),col('type','Type',r=>status(r.type)),col('subject','Subject',r=>`<span class="row-name">${e(r.subject)}</span><small>${e(r.sourceId)}</small>`),col('marketId','Market',r=>e(marketName(r.marketId))),col('priority','Priority',r=>status(r.priority)),col('status','Case state',r=>status(r.status)),col('ageDays','Age',r=>`${r.ageDays} days`),col('dueAt','Review target',r=>`${e(r.dueAt)} ${r.dueAt<DEMO_ASOF?'<span class="status danger">Past due</span>':''}`),col('assignee','Owner',r=>e(r.assignee))],selectors:[{key:'type',label:'Case type',options:types},{key:'priority',label:'Priority',options:['URGENT','HIGH','NORMAL','LOW']},{key:'assignee',label:'Assigned to',options:['A. Kato','P. Akello','J. Okello','S. Namubiru','Unassigned']}],searchKeys:['id','subject','sourceId','type','assignee'],detailType:'request'});
