 `<div class="section-grid equal">${panel('Market occupation comparison','Recorded occupation / registered physical units, not inspected physical utilization',bars(m.map(x=>({name:x.code,value:fac.filter(f=>f.marketId===x.id&&f.status==='OCCUPIED').length}))))}${panel('Market governance coverage','Illustrative manager allocation and readiness prerequisites',m.map(x=>miniStat(e(x.name),e(x.manager))).join('')+callout('<b>Readiness is multi-dimensional:</b> verified manager, Facility records, tenant contracts, inventory handover, audit and approved government revenue mapping.','info'))}</div>`+
 smartTable({id:'marketList',title:'Market registry portfolio',description:'Open a Market to inspect its registered physical population, manager and confirmed sample rent allocations.',rows:m,columns:[col('id','Market',r=>details('market',r.id,r.name)),col('city','Municipality'),col('region','Region'),col('manager','MarketMaster'),col('physical','Physical units',r=>num(D.facilities.filter(f=>f.marketId===r.id).length),r=>D.facilities.filter(f=>f.marketId===r.id).length),col('occupied','Recorded occupied',r=>num(D.facilities.filter(f=>f.marketId===r.id&&f.status==='OCCUPIED').length)),col('collected','Verified allocations',r=>money(sum(D.invoices.filter(i=>i.marketId===r.id),'allocated')))],searchKeys:['name','city','code','manager'],detailType:'market'});
