function permissionDecision(role, market, action){let r=roles[role];let own=r?.market||'all';if(!r)return {ok:false,reason:'Unknown role'};if(action==='financial-post')return{ok:false,reason:'FINANCE HOLD: no role may post in this prototype.'};if(market!=='all'&&role!=='super'&&own!=='all'&&market!==own)return {ok:false,reason:'Market mismatch: requested resource is outside assigned Market.'};if(role==='readonly'&&!['view','export'].includes(action))return{ok:false,reason:'Explicit read-only deny overrides navigation and any grants.'};if(action==='approve'&&!['master','super'].includes(role))return{ok:false,reason:'No administrative approval capability; domain requirements also apply.'};if(action==='gate-admit'&&!['gate','super','master'].includes(role))return{ok:false,reason:'Gate admission restricted to Gate-authorized personnel.'};if(action==='stock-verify'&&!['stock','super','master'].includes(role))return{ok:false,reason:'Stock verification restricted to Stock-authorized personnel.'};if(['vendor','vendor-pending','supplier','supplier-pending','public'].includes(role)&&['view','export'].includes(action))return{ok:false,reason:'Own-record entitlement must be verified; general Market administration not available.'};return{ok:true,reason:'Conditionally permitted in the sample; backend must check grants, resource, status and evidence.'};}
